article_excluded_ids={'u02'}
article_units=[u for u in units if u['id'] not in article_excluded_ids]
build_interactive()
E=html.escape
sources={'[论文 §3.5]':'https://arxiv.org/html/1706.03762v7#S3.SS5','[论文 §3.2.1]':'https://arxiv.org/html/1706.03762v7#S3.SS2.SSS1','[论文 §3.1、§3.2.3]':'https://arxiv.org/html/1706.03762v7#S3.SS1','[Layer Normalization]':'https://arxiv.org/abs/1607.06450'}
def escnote(t):
 s=E(t)
 for label,url in sources.items():s=s.replace(label,f'<a href="{url}" target="_blank" rel="noopener">{label}</a>')
 return s
images={}
for t in sorted(set(t for u in units for t in u['frames'])):
 p=WORK/'frames'/f'{t:06.1f}.jpg'
 im=Image.open(p)
 # Keep entire teaching frame, including existing creator attribution.
 b=io.BytesIO();im.save(b,format='JPEG',quality=90,optimize=True)
 images[t]='data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()
def picture(t,title,i):
 return f'<figure><img src="{images[t]}" alt="{E(title)}：图解{i}" width="1280" height="720"><figcaption>{E(title)} · {i}</figcaption></figure>'
def body(u):
 s=''.join(f'<p data-edit>{E(p)}</p>' for p in u['paragraphs'])
 if u['formula']:s+=f'<div class="formula" data-edit>{E(u["formula"])}</div>'
 if u['note']:s+=f'<aside class="note">{escnote(u["note"])}</aside>'
 return s
chapters=list(dict.fromkeys(u['chapter'] for u in units))
article_chapters=list(dict.fromkeys(u['chapter'] for u in article_units))
chapter_ids={c:next(u['id'] for u in article_units if u['chapter']==c) for c in article_chapters}
nav=''.join(f'<a href="#{chapter_ids[c]}"><span>{i+1:02}</span>{E(c)}</a>' for i,c in enumerate(article_chapters))
